const host=document.querySelector('.hero-visual');
host.innerHTML='<canvas id="village-world" aria-label="Animated miniature village with a dairy, farms, local shops and a moving delivery vehicle"></canvas><div class="scene-title"><span>YOUR VILLAGE. CONNECTED.</span><b>Every resource has a possibility.</b></div><button class="scene-pause" aria-label="Pause village animation">Ⅱ Pause animation</button><div class="scene-legend"><span>● Resources</span><span>● Local market</span><span>● New possibilities</span></div>';
const canvas=document.getElementById('village-world'),ctx=canvas.getContext('2d');let w,h,scale,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,clock=0,last=0,angle=0,targetAngle=0;const button=host.querySelector('button');function sync(){button.textContent=paused?'▶ Play animation':'Ⅱ Pause animation';button.setAttribute('aria-label',paused?'Play village animation':'Pause village animation');}sync();button.onclick=()=>{paused=!paused;sync();};
function resize(){w=host.clientWidth;h=host.clientHeight;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);scale=Math.min(w/690,h/580);}
new ResizeObserver(resize).observe(host);host.addEventListener('pointermove',e=>{if(!paused){const r=host.getBoundingClientRect();targetAngle=((e.clientX-r.left)/r.width-.5)*.13;}});host.addEventListener('pointerleave',()=>targetAngle=0);
function p(x,y,z=0){const xx=x*Math.cos(angle)-y*Math.sin(angle),yy=x*Math.sin(angle)+y*Math.cos(angle);return [w/2+(xx-yy)*.86*scale,h*.50+(xx+yy)*.45*scale-z*scale];}
function poly(points,color){ctx.beginPath();points.forEach((q,i)=>{const v=p(...q);i?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.closePath();ctx.fillStyle=color;ctx.fill();}
function box(x,y,z,dx,dy,dz,c=['#eee2c4','#b6a586','#d1bf9b']){poly([[x,y,z],[x+dx,y,z],[x+dx,y,z+dz],[x,y,z+dz]],c[1]);poly([[x+dx,y,z],[x+dx,y+dy,z],[x+dx,y+dy,z+dz],[x+dx,y,z+dz]],c[2]);poly([[x,y,z+dz],[x+dx,y,z+dz],[x+dx,y+dy,z+dz],[x,y+dy,z+dz]],c[0]);}
function circle(x,y,z,r,c){const q=p(x,y,z);ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(q[0],q[1],r*scale,r*scale,0,0,Math.PI*2);ctx.fill();}
function text(x,y,z,s,size=10,c='#285442'){const q=p(x,y,z);ctx.font=`600 ${size*scale}px sans-serif`;ctx.textAlign='center';ctx.fillStyle=c;ctx.fillText(s,...q);}
function building(x,y,dx,dy,height,title,roof){box(x,y,0,dx,dy,height);poly([[x-5,y-5,height],[x+dx/2,y-5,height+26],[x+dx/2,y+dy+5,height+26],[x-5,y+dy+5,height]],roof);poly([[x+dx/2,y-5,height+26],[x+dx+5,y-5,height],[x+dx+5,y+dy+5,height],[x+dx/2,y+dy+5,height+26]],'#96513a');box(x+dx,y+dy*.4,0,1,dy*.25,height*.58,['#234d45','#244c43','#315f52']);text(x+dx/2,y+dy/2,height+43,title,12);}
function tree(x,y){box(x,y,0,6,6,42,['#ac8458','#745737','#98734b']);circle(x+3,y+3,51,22,'#587d45');circle(x-4,y,60,16,'#799454');circle(x+11,y+5,47,14,'#3b6846');}
function person(x,y,color,t=0){box(x-2,y,0,3,3,13,['#334b52','#243b42','#334b52']);box(x+3,y+Math.sin(t)*3,0,3,3,13,['#334b52','#243b42','#334b52']);box(x-3,y-1,13,10,6,13,[color,color,color]);circle(x+2,y+2,31,5,'#bd875e');}
function cow(x,y){box(x,y,13,26,11,15,['#f5efe1','#e5d9c7','#fff8e7']);box(x-8,y+1,20,10,8,12,['#fff5df','#d1bda5','#f2e2cb']);for(const [a,b] of [[1,1],[20,1],[1,8],[20,8]])box(x+a,y+b,0,3,3,15,['#6b5849','#6b5849','#6b5849']);box(x+10,y,20,8,1,7,['#5c5046','#5c5046','#5c5046']);}
function vehicle(x,y){box(x,y,7,43,23,10,['#deb856','#bf8737','#e0ac44']);box(x,y,17,13,23,20,['#e0ad47','#af7b2d','#c79536']);box(x+14,y,17,29,23,22,['#f1f0dd','#c0d0c1','#d4dfca']);box(x-1,y+3,23,1,16,10,['#a3c7c5','#638f91','#638f91']);for(const a of [7,34]){circle(x+a,y+24,7,6,'#303f3d');circle(x+a,y+24,7,2,'#b8c0b6');}text(x+28,y+28,24,'MILK',7);}
function render(now){if(!last)last=now;if(!paused)clock+=Math.min(40,now-last)/1000;last=now;angle+=(targetAngle-angle)*.035;ctx.clearRect(0,0,w,h);ctx.save();ctx.shadowColor='#294d432a';ctx.shadowBlur=35*scale;ctx.shadowOffsetY=25*scale;poly([[-190,-190,-18],[190,-190,-18],[190,190,-18],[-190,190,-18]],'#5a7451');ctx.restore();box(-190,-190,-18,380,380,18,['#d2dfad','#91a179','#778e68']);poly([[-190,-13,1],[190,-13,1],[190,21,1],[-190,21,1]],'#a5aaa0');poly([[-12,-190,1],[20,-190,1],[20,190,1],[-12,190,1]],'#a5aaa0');for(let i=-170;i<180;i+=32){box(i,2,2,15,2,.2,['#e9e7ce','#e9e7ce','#e9e7ce']);}
for(let i=0;i<7;i++)for(let j=0;j<5;j++){box(-173+i*13,-167+j*19,0,7,13,3,['#867044','#867044','#867044']);circle(-170+i*13,-160+j*19,9+Math.sin(clock*2+i)*1.5,4,'#56874c');}
text(-132,-125,27,'YOUR LAND',10);building(-55,-162,68,65,48,'DAIRY','#c77c4e');tree(75,-160);building(101,-142,58,67,51,'VILLAGE SHOP','#66866b');building(-150,64,64,66,40,'WORKSHOP','#c68551');cow(-54,-65);cow(-14,-65);person(84,-70,'#ca844e',clock*3);person(-80,35+Math.sin(clock*.5)*20,'#41878a',clock*3);vehicle(-160+(clock*24%285),-8);for(let i=0;i<3;i++)box(120+i*12,65,0,10,14,9,['#d5ab66','#a57a42','#bf9450']);tree(154,140);tree(-175,153);person(115,103,'#d5b050');text(130,90,36,'LOCAL BUYERS',10);
for(let i=0;i<3;i++){const t=(clock*.15+i/3)%1,x=-135+t*250,y=135;circle(x,y,12+Math.sin(t*Math.PI)*22,3,'#efbd55');}text(-15,165,10,'RESOURCES → OPPORTUNITY',9);requestAnimationFrame(render);}
resize();requestAnimationFrame(render);
